<?php require __DIR__.'/config/bootstrap.php';header('Content-Type: application/xml; charset=utf-8');$base=rtrim($GLOBALS['config']['base_url'],'/');echo '<?xml version="1.0" encoding="UTF-8"?>';echo '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';echo '<url><loc>'.e($base.'/').'</loc></url>';foreach(db()->query("SELECT slug,updated_at FROM products WHERE status='active'") as $p)echo '<url><loc>'.e($base.'/product.php?slug='.$p['slug']).'</loc><lastmod>'.date('Y-m-d',strtotime($p['updated_at'])).'</lastmod></url>';echo '</urlset>';